// De Voci Belli Chorale — push-only service worker.
//
// Deliberately separate from the app's main PWA service worker (which is
// auto-generated by vite-plugin-pwa at build time and handles offline
// caching). This file is NOT touched by that build step because it has a
// different filename, so it survives every deploy untouched. It does only
// one job: receive push messages and show a notification for them. It has
// no fetch handler, so it never interferes with normal page loads/caching.

self.addEventListener("push", (event) => {
  let data = { title: "De Voci Belli Chorale", body: "You have a new update.", url: "/" };
  try {
    if (event.data) data = { ...data, ...event.data.json() };
  } catch (e) { /* fall back to defaults */ }

  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      data: { url: data.url || "/" },
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url || "/";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clientsList) => {
      for (const client of clientsList) {
        if ("focus" in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(url);
    })
  );
});

